export const meta = {
  name: 'construct-suite',
  description: 'Build the deterministic offline construct suite: harness, fixtures by family, goldens, and a green or gap verdict per row',
  phases: [
    { title: 'Author', detail: 'harness plus one fixture author per construct family, in parallel' },
    { title: 'Integrate', detail: 'write fixtures into the harness branch, capture goldens, run, report green and gap rows' },
  ],
}

const RULES = 'Read /tmp/claude-501/trails3/RULES.txt first (evidence rules, no oracle or corpus runs, signed commits, plain pushes). '

const FIXTURE_SPEC = [
  'FIXTURE FORMAT (exact): each fixture is one self-contained TSX file at apps/oracle/construct-suite/<family>/<NN>-<slug>.tsx that declares ONE props interface named Props with exactly ONE prop named p (optional or required as the construct needs), and exports a single component: export function Row(props: Props) { return null }.',
  'It may declare helper types above Props, and may import types only: import type * as React from "react"; (React types come from apps/oracle node_modules). No runtime code, no side effects, no other exports.',
  'The file MUST type-check cleanly under strict TypeScript; a fixture that does not compile is worthless. Keep each fixture tiny (under 25 lines). One construct per fixture; include the most common real-world spellings first (as used in React design-system props), then edge shapes.',
  'The first line of every file is a comment: // construct: <short name of the construct under test>',
].join('\n')

const FAMILIES = [
  { dir: 'literals', brief: 'string, number, boolean, bigint and template literal types; literal unions (string, numeric, mixed, with null/undefined); the LiteralUnion pattern string & {} and number & {}; enums (string, numeric, const, declare, merged, enum member types); unique symbol; unions with never/unknown/any; negative numeric literals (-1); unions that contain a string literal with a pipe or quote; intersections of literal unions.' },
  { dir: 'objects', brief: 'object type literals and interfaces: optional, readonly, index signatures (string, number, template-literal keys), call signatures only, overloaded call signatures, construct signatures, call signature plus properties, method signatures vs property functions, getters/setters (accessors), computed property names, nested object literals, interfaces that extend others, declaration merging, this-typed members, symbol-keyed members.' },
  { dir: 'tuples-arrays', brief: 'arrays, readonly arrays, tuples: plain, labeled, optional elements, rest elements, variadic tuples, readonly tuples, nested tuples, Array<T> vs T[], ReadonlyArray, arrays of unions (precedence), tuples of functions, empty tuple.' },
  { dir: 'utility-mapped', brief: 'utility and mapped types: Partial, Required, Readonly, Pick, Omit, Record, Exclude, Extract, NonNullable, ReturnType, Parameters, Awaited, keyof, keyof typeof, typeof value, indexed access T[K] and T[keyof T] (including on empty interfaces), mapped types with modifiers (+/-readonly, +/-?) and an as-clause, homomorphic mapped types, conditional types (distributive, infer, nested), alias wrappers around these utilities (type A = Partial<B>; p: A), template literal types built from unions.' },
  { dir: 'generics', brief: 'generics: generic Props<T> with constraint, default type parameter, multiple parameters, a type parameter used in a callback, polymorphic as props (as?: C) with ComponentPropsWithoutRef<C>, generic components instantiated by an alias, this types, recursive types (JSON-like, tree), type parameter shadowing a module type, local interface shadowing a module-level one of the same name inside a function, intersection of generic aliases.' },
  { dir: 'react', brief: 'React-specific: ReactNode, ReactElement, JSX.Element, ReactChild, ReactChildren, children as function (render props), React.FC/FunctionComponent props, ComponentProps<"button">, ComponentPropsWithRef, HTMLAttributes<HTMLDivElement>, CSSProperties, Ref/RefObject/ForwardedRef/LegacyRef, ElementType, ComponentType, event handlers (MouseEventHandler, ChangeEvent callbacks, KeyboardEvent), aria and data-* props, style systems (sx-like props as plain object types), Key, SyntheticEvent, Dispatch<SetStateAction<T>>, forwardRef and memo wrappers around props types (declare the props type only; the component stays a plain Row export).' },
]

const FIXTURES_SCHEMA = {
  type: 'object',
  properties: {
    files: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          path: { type: 'string' },
          content: { type: 'string' },
          construct: { type: 'string' },
        },
        required: ['path', 'content', 'construct'],
      },
    },
    skipped: {
      type: 'array',
      items: { type: 'object', properties: { construct: { type: 'string' }, why: { type: 'string' } }, required: ['construct', 'why'] },
    },
  },
  required: ['files'],
}

const HARNESS_SCHEMA = {
  type: 'object',
  properties: {
    branch: { type: 'string' },
    commit: { type: 'string' },
    command: { type: 'string' },
    layout: { type: 'string' },
    notes: { type: 'string' },
  },
  required: ['branch', 'commit', 'command', 'layout'],
}

const INTEGRATE_SCHEMA = {
  type: 'object',
  properties: {
    commit: { type: 'string' },
    rows: { type: 'number' },
    green: { type: 'number' },
    gaps: { type: 'array', items: { type: 'object', properties: { row: { type: 'string' }, verdict: { type: 'string' }, why: { type: 'string' } }, required: ['row', 'verdict', 'why'] } },
    invalid: { type: 'array', items: { type: 'object', properties: { row: { type: 'string' }, error: { type: 'string' } }, required: ['row', 'error'] } },
    command: { type: 'string' },
    seconds: { type: 'number' },
    ci: { type: 'string' },
  },
  required: ['commit', 'rows', 'green', 'gaps', 'invalid', 'command'],
}

phase('Author')

const harnessPromise = agent(
  RULES +
    'Build the HARNESS for the deterministic construct suite on a new branch feat/construct-suite from fresh origin/main (trail #258 "Deterministic construct suite", repo gh/orin-dx/caliper; link with `entire trail link 258 --branch feat/construct-suite --base main --repo gh/orin-dx/caliper` after pushing, retry after a pause; the PR is opened by Entire, do not run gh pr create). Files: apps/oracle only (new script, new test, new directory apps/oracle/construct-suite/). Read apps/oracle/src/oracle.ts, oracle-checker.ts, oracle-compare.ts, tool-norm.ts and docs/measurement.md first. The suite works like this: fixtures live at apps/oracle/construct-suite/<family>/<NN>-<slug>.tsx (one props interface Props with one prop p, exported Row component; other workers are writing them right now, you write 3 seed rows of your own in family "seed" to prove the harness). (1) A capture script (`pnpm --filter caliper-docgen-oracle construct:capture`) runs the Go checker (typescript-beta/sync, the independent arbiter) over all fixtures in ONE program and writes, per fixture, a committed golden file next to it (<name>.golden.json: the checker-side normalized type of prop p, using the oracle-checker normalization, plus the checker typeToString text). Provide `--check` mode that re-captures and fails on any diff (used when the TypeScript pin changes). (2) A test (`construct-suite.test.ts` under apps/oracle/tests, run by vitest with the package tests) takes caliper output for each fixture (run the caliper binary from env CALIPER_BIN, default target/release/caliper-docgen, with the canonical JSON options the weekly uses minus --load-dependencies if not needed; one extract invocation over the whole directory) and compares prop p with the golden through compareOne from oracle-compare.ts, giving a verdict identical, spelled, less precise, wrong, or opaque-with-marker (degradedBy present). (3) An expectations file apps/oracle/construct-suite/expectations.json maps every row id to its allowed verdict set; a row either must be identical/spelled, or is listed as a documented gap with a reason string; the test FAILS if a row is better or worse than its expectation (so improvements force the expectation to be updated and regressions are caught). When CALIPER_BIN is missing the test skips with a clear message and the package test still passes; add a CI note in the README of the directory on how CI should build the binary (do not edit workflows). (4) A short README.md in apps/oracle/construct-suite/ explaining the layout, the two commands, how to add a row, and what green/gap means. Run the oracle package tests, tsc, `just lint doc-check machete typos` (read exit status) and a clean-room run per the rules; signed commits; plain push of feat/construct-suite; keep the seed rows. Report the exact commands, layout and anything the integrator must know.',
  { label: 'harness', phase: 'Author', isolation: 'worktree', effort: 'medium', schema: HARNESS_SCHEMA },
)

const authorPromises = FAMILIES.map((f) =>
  agent(
    RULES +
      'You are a fixture author for the construct suite. You do NOT edit the repository: you RETURN the fixture files as data (the integrator writes them). You may read the repo (apps/oracle/src, docs/rdt-differences.md, docs/edge-cases.md) for context. ' +
      FIXTURE_SPEC +
      '\nYour family directory: apps/oracle/construct-suite/' + f.dir + '/ . Constructs to cover (be exhaustive within this brief, aim for 20 to 35 fixtures, most common real-world spellings first): ' + f.brief +
      '\nBefore returning, type-check every fixture mentally against strict TypeScript; if a construct cannot be expressed in the fixture format, list it in skipped with the reason. Number files 01, 02, ... in order and make slugs unique. Return only data.',
    { label: 'author:' + f.dir, phase: 'Author', effort: 'low', schema: FIXTURES_SCHEMA },
  ),
)

const results = await Promise.all([harnessPromise, ...authorPromises])
const harness = results[0]
const authored = results.slice(1).filter(Boolean)
if (!harness) {
  log('harness agent failed; nothing to integrate')
  return { error: 'harness failed', authored: authored.map((a) => a.files.length) }
}
const allFiles = authored.flatMap((a) => a.files)
const skipped = authored.flatMap((a) => a.skipped || [])
log('fixtures authored: ' + allFiles.length + ', skipped: ' + skipped.length + ', families returned: ' + authored.length + '/' + FAMILIES.length)

phase('Integrate')

const integrated = await agent(
  RULES +
    'Integrate the construct suite. Branch feat/construct-suite already exists on origin with the harness (trail #258; commit ' + harness.commit + '; commands: ' + harness.command + '; layout: ' + harness.layout + '). In your worktree: git fetch --prune; git checkout -B feat/construct-suite origin/feat/construct-suite. Write ALL the fixture files below into apps/oracle/construct-suite/ exactly at the given paths (JSON array, each {path, content}); drop any whose path is outside apps/oracle/construct-suite/<family>/ or whose name does not match NN-slug.tsx, and report them. Then: (1) type-check all fixtures with strict TypeScript in ONE program (the capture script or tsc over the directory); any fixture that does not compile: fix it if the fix is trivial and obviously keeps the construct under test, else delete it and report it in invalid; (2) run the capture script to write goldens from the Go checker; (3) build the caliper release binary from this branch (cargo build --release -p caliper-docgen; CALIPER_BIN) and run the suite; for each row compute the verdict; seed expectations.json: rows that score identical or spelled are green; rows that score less precise, wrong or opaque are documented GAPS with a one-line reason derived by reading caliper output vs the golden (be specific: which construct and what differs); NEVER mark a row green that is not; (4) the suite must run in seconds: report the wall time; (5) run the oracle package tests, tsc, `just lint doc-check machete typos` (read exit status) and a clean-room run per the rules; signed commit(s), plain push to feat/construct-suite (no force); do not edit the PR body. Skipped constructs from the authors (list them in the README as not expressible as one-prop fixtures): ' + JSON.stringify(skipped) + '\nFIXTURES: ' + JSON.stringify(allFiles.map((f) => ({ path: f.path, content: f.content }))) +
    '\nReturn the counts and every gap row with its verdict and reason, the invalid list, the command, the wall seconds and the CI check status you can read.',
  { label: 'integrate', phase: 'Integrate', isolation: 'worktree', effort: 'medium', schema: INTEGRATE_SCHEMA },
)

return { harness, authoredFamilies: authored.length, fixtures: allFiles.length, skipped, integrated }

